package caddyfile

import "testing"

func TestIssue5761Temp(t *testing.T) {
	input := []byte(`localhost {
  templates {
    between <<  >>
  }
}
`)
	tokens, err := Tokenize(input, "Caddyfile")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	var texts []string
	for _, tok := range tokens {
		texts = append(texts, tok.Text)
	}
	t.Logf("tokens: %v", texts)
	want := []string{"localhost", "{", "templates", "{", "between", "<<", ">>", "}", "}"}
	if len(texts) != len(want) {
		t.Fatalf("token count mismatch: got %v", texts)
	}
	for i := range want {
		if texts[i] != want[i] {
			t.Fatalf("token %d: got %q, want %q", i, texts[i], want[i])
		}
	}

	// heredoc must still work
	heredocInput := []byte(`respond <<HTML
	<html>
	HTML 201
`)
	tokens2, err := Tokenize(heredocInput, "Caddyfile")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	var texts2 []string
	for _, tok := range tokens2 {
		texts2 = append(texts2, tok.Text)
	}
	t.Logf("heredoc tokens: %v", texts2)
	if len(texts2) != 3 || texts2[1] != "<html>" || texts2[2] != "201" {
		t.Fatalf("heredoc tokens mismatch: %v", texts2)
	}
}
